/**
 * Phase 05's paired test: the `tell` family.
 *
 * The catalog rows were GENERATED by a regex over the rule modules. If this test
 * verified them with the same regex it would be green by construction and blind
 * to whatever the regex cannot see — a tautology that already cost this repo six
 * missing checks and two wrong severities. So the pairing here is against
 * RUNTIME state: the imported roster and what the linter actually emits.
 *
 * Two further contracts:
 *  - rules import nothing from an extractor, or the family is web-only again;
 *  - every rule can fire AND stay silent, proven per rule, not sampled.
 */
import { describe, expect, it } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { TELL_RULES, TELL_REQUIREMENTS, lintTell, tellCoverage } from "../src/core/tell-lint.js";
import { CHECK_CATALOG } from "../src/core/check-catalog.js";
import { RENDERED_RULES } from "../src/core/tell-rules-rendered.js";
import { GATE_FAMILIES } from "../src/core/gate.js";
import { EXTRACTOR_PROFILES, extractorById } from "../src/core/design-facts/index.js";
import type { DesignFact, Provenance } from "../src/core/design-facts/index.js";

const CORE = join(fileURLToPath(new URL("..", import.meta.url)), "src", "core");

const html = extractorById("html-cascade")!;
const swift = extractorById("swiftui")!;

const at = (line = 1): Provenance => ({ file: "f", line, extractor: "html-cascade", confidence: "resolved" });

describe("family registration", () => {
  it("is a gate family", () => {
    expect(GATE_FAMILIES).toContain("tell");
  });

  it("pairs the catalog against the RUNTIME roster, not against its own generator", () => {
    // The family has two rosters with different shapes: 36 rules over facts and
    // 7 over a settled render. Pairing against only the first would let a
    // rendered row rot unnoticed — the catalog must account for both.
    const fromRuntime = new Set([...TELL_RULES, ...RENDERED_RULES].map((r) => r.id));
    const fromCatalog = new Set(CHECK_CATALOG.filter((e) => e.family === "tell").map((e) => e.id));
    expect([...fromRuntime].sort()).toEqual([...fromCatalog].sort());
    expect(TELL_RULES).toHaveLength(36);
    expect(RENDERED_RULES).toHaveLength(7);
  });

  it("declares in the catalog exactly the fact kinds each rule declares at runtime", () => {
    for (const rule of TELL_RULES) {
      const row = CHECK_CATALOG.find((e) => e.id === rule.id && e.family === "tell");
      expect(row, rule.id).toBeDefined();
      const requires = row?.requires;
      expect(typeof requires, rule.id).toBe("object");
      if (typeof requires === "object") {
        expect([...requires.facts].sort(), rule.id).toEqual([...rule.needs].sort());
      }
    }
  });

  it("has no duplicate ids and every id is kebab-case", () => {
    const ids = TELL_RULES.map((r) => r.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of ids) expect(id).toMatch(/^[a-z][a-z0-9-]*$/);
  });

  it("cites a section that exists in knowledge/design-tells.md", () => {
    const doc = readFileSync(join(CORE, "..", "..", "knowledge", "design-tells.md"), "utf8");
    for (const rule of TELL_RULES) {
      expect(doc, rule.id).toContain(`## ${rule.section}`);
      // The standard must actually describe the rule it claims to emit.
      expect(doc, rule.id).toContain(`**${rule.id}**`);
    }
    // The rendered rules carry no `section` field, but the standard still owes
    // each one a description — a rule the knowledge never mentions is a rule
    // nobody agreed to.
    expect(doc).toContain("## Rendered");
    for (const rule of RENDERED_RULES) expect(doc, rule.id).toContain(`**${rule.id}**`);
  });

  it("defaults to advisory — a tell prints, it does not fail a build", () => {
    const errors = TELL_RULES.filter((r) => r.severity === "error").map((r) => r.id);
    expect(errors.sort()).toEqual(["gradient-text", "justified-text", "side-tab"]);
    expect(TELL_RULES.every((r) => r.severity === "error" || r.severity === "advisory")).toBe(true);
  });
});

describe("architecture boundary", () => {
  it("rules import nothing from an extractor", () => {
    const ruleFiles = readdirSync(CORE).filter((f) => /^tell-rules(-\w+)?\.ts$/.test(f));
    expect(ruleFiles.length).toBeGreaterThanOrEqual(5);
    for (const f of ruleFiles) {
      const src = readFileSync(join(CORE, f), "utf8");
      // Strip comments first: a docblock mentioning extractors must not fail
      // this, and matching prose instead of code is a real way to fake a guard.
      const code = src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
      expect(code, f).not.toMatch(/from\s+"\.\/extractors\//);
      expect(code, f).not.toMatch(/htmlparser2|css-tree|css-select/);
    }
  });
});

describe("NOT-EVALUATED, never a silent pass", () => {
  it("reports structure-dependent rules as not-evaluated on a literal-tier extractor", () => {
    const r = lintTell([], swift);
    const ids = r.notEvaluated.map((n) => n.id);
    // swiftui supplies no `structure`, so every rule needing it must be here.
    expect(ids).toContain("nested-cards");
    expect(ids).toContain("monotonous-spacing");
    expect(ids).toContain("icon-tile-stack");
    for (const n of r.notEvaluated) expect(n.reason).toContain("missing");
  });

  it("runs every rule on the reference extractor", () => {
    expect(lintTell([], html).notEvaluated).toEqual([]);
  });

  it("builds a rule x extractor matrix over every registered extractor", () => {
    // All 43: the 36 fact rules AND the 7 rendered ones. Listing only the first
    // set would leave the rendered rules invisible, and a rule nobody can see is
    // a rule nobody notices has stopped running.
    const matrix = tellCoverage(EXTRACTOR_PROFILES);
    expect(matrix).toHaveLength(43);
    for (const row of matrix) expect(row.byExtractor).toHaveLength(EXTRACTOR_PROFILES.length);
    // The rendered rules run against exactly one extractor, and are
    // NOT-EVALUATED against every other.
    const hidden = matrix.find((r) => r.id === "content-hidden-at-rest");
    const runsOn = hidden?.byExtractor.filter((b) => b.runnable).map((b) => b.extractor);
    expect(runsOn).toEqual(["rendered-cdp"]);
  });
});

