describe("every rule fires, and stays silent on nothing", () => {
  it("covers the whole roster — a missing entry is a rule nobody proved", () => {
    expect(Object.keys(FIRES).sort()).toEqual(TELL_RULES.map((r) => r.id).sort());
  });

  for (const rule of TELL_RULES) {
    it(`${rule.id} fires on its own evidence`, () => {
      const r = lintTell(FIRES[rule.id] as DesignFact[], html);
      expect(r.findings.map((f) => f.checkId), rule.id).toContain(rule.id);
      const mine = r.findings.filter((f) => f.checkId === rule.id);
      for (const f of mine) {
        expect(f.fixHint, `${rule.id} needs a repair clause`).toBeTruthy();
        expect(f.section).toBe(rule.section);
      }
    });
  }

  it("emits nothing at all on an empty artifact", () => {
    const r = lintTell([], html);
    expect(r.findings).toEqual([]);
    expect(r.errorCount + r.warningCount + r.advisoryCount).toBe(0);
  });

  it("never lets an advisory finding change the failure count", () => {
    const r = lintTell(FIRES["cream-palette"] as DesignFact[], html);
    expect(r.advisoryCount).toBeGreaterThan(0);
    expect(r.errorCount).toBe(0);
  });

  it("orders findings deterministically", () => {
    const facts = Object.values(FIRES).flat();
    const a = JSON.stringify(lintTell(facts, html).findings);
    const b = JSON.stringify(lintTell([...facts].reverse(), html).findings);
    expect(a).toBe(b);
  });
});

describe("the false-positive floor", () => {
  it("does not call two radii in one flat file `nested-cards`", () => {
    const flat: DesignFact[] = [
      { kind: "structure", node: "div", depth: 1, ref: "a", roles: ["card"], at: at(1) },
      { kind: "structure", node: "div", depth: 1, ref: "b", roles: ["card"], at: at(2) },
      { kind: "radius", px: 16, at: at(1) },
      { kind: "radius", px: 12, at: at(2) },
    ];
    expect(lintTell(flat, html).findings.map((f) => f.checkId)).not.toContain("nested-cards");
  });

  it("does not call a three-padding component `monotonous-spacing`", () => {
    const small: DesignFact[] = [
      { kind: "structure", node: "div", depth: 0, ref: "r", at: at(1) },
      { kind: "spacing", prop: "padding-top", px: 16, at: at(1) },
      { kind: "spacing", prop: "padding-left", px: 16, at: at(1) },
      { kind: "spacing", prop: "padding-right", px: 16, at: at(1) },
    ];
    expect(lintTell(small, html).findings.map((f) => f.checkId)).not.toContain("monotonous-spacing");
  });

  it("does not call one kicker a template", () => {
    const one: DesignFact[] = [
      { kind: "text", content: "WHY IT MATTERS", role: "body", at: at(1) },
      { kind: "typography", transform: "uppercase", sizePx: 12, at: at(1) },
    ];
    expect(lintTell(one, html).findings.map((f) => f.checkId)).not.toContain("kicker-above-heading");
  });

  it("does not call a system face overused", () => {
    for (const family of ["SF Pro", "-apple-system", "Sohne", "Georgia"]) {
      const r = lintTell([{ kind: "typography", family, at: at(1) }], html);
      expect(r.findings.map((f) => f.checkId), family).not.toContain("overused-font");
    }
  });

  it("does not call a component's UI chrome scale a flat hierarchy", () => {
    // Measured on a real React app: 27 of 27 hits were 12/14/16px in component
    // files — text-xs/text-sm/text-base, which is interface text, not a broken
    // heading scale. A fragment has no display type to be flat.
    const chrome: DesignFact[] = [12, 14, 16].map((n, i) => ({ kind: "typography", sizePx: n, at: at(i + 1) }));
    expect(lintTell(chrome, html).findings.map((f) => f.checkId)).not.toContain("flat-type-hierarchy");
  });

  it("does not call a pill's padding cramped", () => {
    // `rounded-full` IS the chip case. The first threshold exempted only SMALL
    // radii and so flagged most pills in a real app.
    const pill: DesignFact[] = [
      { kind: "spacing", prop: "padding-top", px: 4, at: at(1) },
      { kind: "radius", px: 999, at: at(1) },
    ];
    expect(lintTell(pill, html).findings.map((f) => f.checkId)).not.toContain("cramped-padding");
  });

  it("still calls a real card's 4px padding cramped", () => {
    const card: DesignFact[] = [
      { kind: "spacing", prop: "padding-top", px: 4, at: at(1) },
      { kind: "radius", px: 16, at: at(1) },
    ];
    expect(lintTell(card, html).findings.map((f) => f.checkId)).toContain("cramped-padding");
  });

  it("does not call a well-ranked type scale flat", () => {
    const scale: DesignFact[] = [12, 16, 24, 40].map((n, i) => ({ kind: "typography", sizePx: n, at: at(i + 1) }));
    expect(lintTell(scale, html).findings.map((f) => f.checkId)).not.toContain("flat-type-hierarchy");
  });
});

describe("requirement view", () => {
  it("mirrors the roster exactly", () => {
    expect(TELL_REQUIREMENTS.map((r) => r.id).sort()).toEqual(TELL_RULES.map((r) => r.id).sort());
  });
});

/**
 * Guards that the first version of this suite did NOT actually guard.
 *
 * Breaking five knobs left it green: the NOT-EVALUATED bypass, side-tab's
 * one-side condition, nested-cards' parent check, the purple threshold, and the
 * deduplicator. Each was "obviously" covered by a nearby assertion that turned
 * out to test something else. These are the probes that go red.
 */
describe("guards proven by breaking them", () => {
  it("does not RUN a rule the extractor cannot feed — not merely list it", () => {
    // Hand the swiftui profile facts that WOULD trip a structure rule. Listing
    // nested-cards under notEvaluated is not enough: the rule must not fire.
    const facts: DesignFact[] = [
      { kind: "structure", node: "VStack", depth: 1, ref: "outer", roles: ["card"], at: at(1) },
      { kind: "structure", node: "VStack", depth: 2, ref: "inner", parentRef: "outer", roles: ["card"], at: at(2) },
    ];
    const r = lintTell(facts, swift);
    expect(r.findings.map((f) => f.checkId)).not.toContain("nested-cards");
    expect(r.notEvaluated.map((n) => n.id)).toContain("nested-cards");
  });

  it("does not call a four-sided border a side-tab", () => {
    const facts: DesignFact[] = [
      { kind: "border", sides: ["top", "right", "bottom", "left"], widthPx: 4, at: at(1) },
      { kind: "radius", px: 16, at: at(1) },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).not.toContain("side-tab");
  });

  it("does not call a thin one-sided rule a side-tab", () => {
    const facts: DesignFact[] = [
      { kind: "border", sides: ["bottom"], widthPx: 1, at: at(1) },
      { kind: "radius", px: 16, at: at(1) },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).not.toContain("side-tab");
  });

  it("does not call a card inside a NON-card `nested-cards`", () => {
    const facts: DesignFact[] = [
      { kind: "structure", node: "section", depth: 0, ref: "sec", at: at(1) },
      { kind: "structure", node: "div", depth: 1, ref: "card", parentRef: "sec", roles: ["card"], at: at(2) },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).not.toContain("nested-cards");
  });

  it("does not call navy, plum or teal the AI palette", () => {
    for (const hex of ["1e3a5f", "0b1f3a", "4a1f3d", "0f766e", "1f2937"]) {
      const r = lintTell([{ kind: "color", hex, role: "bg", at: at(1) }], html);
      expect(r.findings.map((f) => f.checkId), `#${hex}`).not.toContain("ai-color-palette");
    }
  });

  it("still calls the real purple family the AI palette", () => {
    for (const hex of ["7c3aed", "a855f7", "6366f1", "8b5cf6"]) {
      const r = lintTell([{ kind: "color", hex, role: "bg", at: at(1) }], html);
      expect(r.findings.map((f) => f.checkId), `#${hex}`).toContain("ai-color-palette");
    }
  });

  it("collapses identical findings from one declaration matching many elements", () => {
    // One stylesheet line, two elements — same line, same node locator absent.
    const dup: DesignFact[] = [
      { kind: "border", sides: ["left"], widthPx: 4, at: at(4) },
      { kind: "border", sides: ["left"], widthPx: 4, at: at(4) },
      { kind: "radius", px: 16, at: at(4) },
    ];
    const sideTabs = lintTell(dup, html).findings.filter((f) => f.checkId === "side-tab");
    expect(sideTabs).toHaveLength(1);
  });

  it("collapses the same mistake on two elements into one finding with a count", () => {
    // Two elements, one authored decision. Reporting it twice makes the reader
    // scroll; reporting it once with the count and an example is the finding
    // they can act on. Measured on a real page: 54 identical lines in one file.
    const two: DesignFact[] = [
      { kind: "border", sides: ["left"], widthPx: 4, at: { ...at(4), nodeRef: "div.a" } },
      { kind: "border", sides: ["left"], widthPx: 4, at: { ...at(4), nodeRef: "div.b" } },
      { kind: "radius", px: 16, at: at(4) },
    ];
    const sideTabs = lintTell(two, html).findings.filter((f) => f.checkId === "side-tab");
    expect(sideTabs).toHaveLength(1);
    expect(sideTabs[0]?.message).toContain("2 elements");
    expect(sideTabs[0]?.nodeRef).toBe("div.a");
  });

  it("keeps DIFFERENT mistakes apart even on the same line", () => {
    const mixed: DesignFact[] = [
      { kind: "border", sides: ["left"], widthPx: 4, at: { ...at(4), nodeRef: "div.a" } },
      { kind: "border", sides: ["right"], widthPx: 6, at: { ...at(4), nodeRef: "div.b" } },
      { kind: "radius", px: 16, at: at(4) },
    ];
    expect(lintTell(mixed, html).findings.filter((f) => f.checkId === "side-tab")).toHaveLength(2);
  });
});

describe("the purple threshold, pinned by both sides", () => {
  const isPalette = (hex: string) =>
    lintTell([{ kind: "color", hex, role: "bg", at: at(1) }], html)
      .findings.map((f) => f.checkId).includes("ai-color-palette");

  it("catches the whole violet family, indigo included", () => {
    for (const hex of ["7c3aed", "a855f7", "6366f1", "8b5cf6", "9333ea", "4f46e5"])
      expect(isPalette(hex), `#${hex} should be caught`).toBe(true);
  });

  it("leaves blue, navy, teal and plum alone", () => {
    for (const hex of ["2563eb", "3b82f6", "4169e1", "1e3a5f", "0f766e", "4a1f3d", "1f2937"])
      expect(isPalette(hex), `#${hex} should NOT be caught`).toBe(false);
  });
});

/**
 * Owner pairing. `sameOwner` is an existence check; `nearestOwner` is "THE
 * partner". Confusing them let heading-rhythm read the h2's size for the h1 the
 * moment a line window replaced line equality, so both directions are pinned.
 */
describe("owner pairing", () => {
  it("pairs a heading with ITS size, not with a neighbour's", () => {
    const facts: DesignFact[] = [
      { kind: "text", content: "H1", role: "heading", level: 1, at: at(10) },
      { kind: "typography", sizePx: 48, at: at(10) },
      { kind: "text", content: "H2", role: "heading", level: 2, at: at(11) },
      { kind: "typography", sizePx: 24, at: at(11) },
    ];
    // A correct scale: h1 48 > h2 24. Mispairing inverts it and fires the rule.
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).not.toContain("heading-rhythm");
  });

  it("still catches a genuinely inverted heading scale", () => {
    const facts: DesignFact[] = [
      { kind: "text", content: "H1", role: "heading", level: 1, at: at(10) },
      { kind: "typography", sizePx: 24, at: at(10) },
      { kind: "text", content: "H2", role: "heading", level: 2, at: at(20) },
      { kind: "typography", sizePx: 48, at: at(20) },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).toContain("heading-rhythm");
  });

  it("treats consecutive modifier lines as one owner when no node is named", () => {
    // The native shape: radius on one line, the edge bar on the next.
    const facts: DesignFact[] = [
      { kind: "radius", px: 16, at: { file: "v.swift", line: 24, extractor: "swiftui", confidence: "literal" } },
      { kind: "border", sides: ["left"], widthPx: 4, at: { file: "v.swift", line: 25, extractor: "swiftui", confidence: "literal" } },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).toContain("side-tab");
  });

  it("does NOT join facts from unrelated parts of a file", () => {
    const facts: DesignFact[] = [
      { kind: "radius", px: 16, at: { file: "v.swift", line: 10, extractor: "swiftui", confidence: "literal" } },
      { kind: "border", sides: ["left"], widthPx: 4, at: { file: "v.swift", line: 90, extractor: "swiftui", confidence: "literal" } },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).not.toContain("side-tab");
  });

  it("never joins facts from different files", () => {
    const facts: DesignFact[] = [
      { kind: "radius", px: 16, at: { file: "a.swift", line: 10, extractor: "swiftui", confidence: "literal" } },
      { kind: "border", sides: ["left"], widthPx: 4, at: { file: "b.swift", line: 10, extractor: "swiftui", confidence: "literal" } },
    ];
    expect(lintTell(facts, html).findings.map((f) => f.checkId)).not.toContain("side-tab");
  });
});
